// Which holiday a date falls in, by the person's local calendar.
function holidayOf(now        )                 {
  const date = new Date(now)
  const month = date.getMonth() + 1
  const day = date.getDate()
  const between = (m        , from        , to        ) => month === m && day >= from && day <= to

  if (between(10, 15, 31)) return HOLIDAYS.halloween 
  if (between(12, 1, 26)) return HOLIDAYS.christmas 
  if (between(12, 27, 31) || between(1, 1, 2)) return HOLIDAYS.newyear 
  if (between(2, 10, 14)) return HOLIDAYS.valentine 
  if (between(3, 14, 17)) return HOLIDAYS.stpatrick 
  if (between(7, 1, 4)) return HOLIDAYS.july4 
  if (month === 11) {
    // Thanksgiving week: up to and including the fourth Thursday.
    const first = new Date(date.getFullYear(), 10, 1).getDay()
    const fourthThursday = 1 + ((4 - first + 7) % 7) + 21
    if (day >= fourthThursday - 4 && day <= fourthThursday) return HOLIDAYS.thanksgiving 
  }
  return null
}

// A stable "random" pick per agent: hashed from its id, so a sprite keeps its
// costume across redraws, and two agents usually differ.
function costumeOf(holiday                , id        )                 {
  if (!holiday) return null
  let hash = 0
  for (let i = 0; i < id.length; i += 1) hash = (hash * 31 + id.charCodeAt(i)) >>> 0
  return holiday.costumes[hash % holiday.costumes.length] ?? null
}

