/** One gag. `caption` finishes the sentence "He's …" under the bar. */
                                                                                      

/** The sprite is drawn this many times its 16px size. */
const SCALE = 1.5
/** Its drawn size in px. */
const SIZE = 16 * SCALE

const px = (x        , y        , w        , h        , fill        ) =>
  `<rect x="${x}" y="${y}" width="${w}" height="${h}" fill="${fill}"/>`

/** An animateTransform that loops forever and adds to the element's transform. `begin` must not be negative. */
const spin = (attrs        , dur        , begin = 0) =>
  `<animateTransform attributeName="transform" ${attrs} dur="${dur}s" begin="${begin}s" repeatCount="indefinite" additive="sum"/>`

/** An attribute animation that loops forever. */
const loop = (attr        , values        , dur        , begin = 0, extra = '') =>
  `<animate attributeName="${attr}" values="${values}" dur="${dur}s" begin="${begin}s" repeatCount="indefinite"${extra ? ' ' + extra : ''}/>`

/** Places drawn content with its top-left at (x, y), scaled. */
const at = (x        , y        , inner        , scale = 1) =>
  `<g transform="translate(${round(x)} ${round(y)})${scale === 1 ? '' : ` scale(${scale})`}">${inner}</g>`

/** The sprite standing with its feet on the track, its left edge at x; `inner` animations go inside its group. */
const standing = (c           , x        , face             = 'neutral', motion = '') =>
  at(x, c.trackY - SIZE, `<g>${motion}${c.sprite(face)}</g>`, SCALE)

const round = (n        ) => Math.round(n * 10) / 10

/** Builds the sprite function for a context. */
function spriteFn(color        , costume                )                                {
  const ink = costume?.face ?? INK
  return face => spritePixels(color, 'running', costume, face ? facePixels(face, ink) : undefined)
}

/**
 * The sample gag, and the fallback: he leans into the bar's end and shoves, legs
 * pumping, a puff of dust kicking up behind him.
 */
const SHOVE         = {
  name: 'shove',
  caption: 'shoving it along',
  draw: c => {
    const sx = Math.max(0, c.x - SIZE + 4)
    const lean = spin('type="rotate" values="12 12 24;18 12 24;12 12 24"', 0.5)
    const step = spin('type="translate" values="0 0;-1 0;0 0;1 0;0 0"', 0.5)
    const dust =
      `<g opacity="0">${loop('opacity', '0;0.8;0', 0.5)}` +
      `<circle cx="${round(sx)}" cy="${c.trackY - 2}" r="2" fill="#b8a07a">${loop('r', '1;3;1', 0.5)}${loop('cx', `${sx};${sx - 6};${sx}`, 0.5)}</circle></g>`
    return dust + standing(c, sx, 'scowl', lean + step)
  },
}

return { SCALE, SIZE, px, spin, loop, at, standing, round, spriteFn, SHOVE };
