    shown('0;1;0', '0;0.5;1', 0.4, px(-2, -7, 1, 1, tyre) + px(-1, -6, 1, 1, tyre) + px(1, -6, 1, 1, tyre) + px(2, -7, 1, 1, tyre) + px(-2, -3, 1, 1, tyre) + px(-1, -4, 1, 1, tyre) + px(1, -4, 1, 1, tyre) + px(2, -3, 1, 1, tyre)) +
    px(0, -5, 1, 1, c.ink)
  const barrowArt =
    line(-11, -11, -21, -5, '#a0693a') +
    px(-9, -9, 1, 3, c.ink) + px(-10, -6, 2, 1, c.ink) +
    blob(HEAP, c.fill, c.ink, 0, -19) + px(-8, -18, 3, 1, mix(c.fill, 255, 0.35)) +
    blob(TRAY, steel, c.ink, 0, -16) + px(-13, -15, 15, 1, mix(steel, 255, 0.3)) +
    px(-2, -9, 1, 2, c.ink) + px(-1, -7, 1, 2, c.ink)
  const barrow = at(
    wx,
    c.trackY,
    `<g>${nudge(jolt, keys, dur)}${wheel}<g>${T('rotate', tilts.map(a => `${a} 0.5 -4.5`), dur, kt(keys))}${barrowArt}</g></g>`,
    SCALE,
  )

