    const sy = 15
    const T = 2.4
    const beat = keys(0, 0.55, 0.65, 0.8, 1)
    const sway                     = [
      [0, 0],
      [3, 1],
      [-1, 2.5],
      [0.5, 1],
      [0, 0],
    ]
    const swing = [-4, 6, -6, 2, -4]
