    const hop = keys(0, 0.62, 0.7, 0.8, 1)
    const body = lean('-18;-24;-18', 0.4, faces(c, 'scowl', 'xeyes', 0.62, 0.85, T))
    const runner =
      `<g>${tf('translate', '0 0;0 0;0 -3;0 0;0 0', T, 0, hop)}` +
      at(sx, sy, `<g>${tf('translate', '0 0;1 0;0 0;-1 0;0 0', 0.4)}${body}</g>`, SCALE) +
      during(0.62, 0.85, T, bang(sx + 26, sy - 2)) +
      '</g>'
    const handY = sy + 12
    const contact = push
