/** The task-list step a part follows: the first whose text contains `text`, any case. */
function planStepFor(plan                     , text        )                       {
  const want = text.trim().toLowerCase()
  return plan.find(step => step.content.toLowerCase().includes(want))
}

             
                                       
                    
                     
                   
                       
 

const plural = (n        , word        ) => `${n} ${word}${n === 1 ? '' : 's'}`

/** What tracking says a part's state is, or undefined when nothing it follows has started. */
function autoFor(part              , agents                         , plan                     , now        )                   {
  const t = part.track
  if (!t) return undefined
  if (t.agents) {
    const found = matching(agents, t.agents)
    if (found.length > 0) {
      const n = found.length
      const done = found.filter(a => a.status === 'done').length
      const failed = found.filter(a => a.status === 'failed').length
      const startedAt = Math.min(...found.map(a => a.startedAt))
      const failedNote = failed > 0 ? `, ${failed} failed` : ''
      if (done + failed < n) {
        return { status: 'running', startedAt, progress: `${done} of ${plural(n, 'agent')} done${failedNote}`, progressFrac: (done + failed) / n }
      }
      const finishedAt = Math.max(...found.map(a => a.endedAt ?? now))
      if (failed > 0) return { status: 'failed', startedAt, finishedAt, progress: `${failed} of ${plural(n, 'agent')} failed`, progressFrac: 1 }
      return { status: 'done', startedAt, finishedAt, progress: n === 1 ? '1 agent done' : `all ${n} agents done`, progressFrac: 1 }
    }
  }
  if (t.plan) {
    const step = planStepFor(plan, t.plan)
    if (step?.status === 'in_progress') return { status: 'running' }
    if (step?.status === 'completed') return { status: 'done' }
  }
  return undefined
}

/**
 * The schedule with every tracked part moved to what tracking says, or undefined when
 * nothing changes. A part pinned by hand (done or failed) is left as it is.
 */
function derive(schedule          , agents                         , plan                     , now        )                       {
  let changed = false
  const parts = schedule.parts.map(part => {
    if (part.pinned || !part.track) return part
    const auto = autoFor(part, agents, plan, now)
    if (!auto) return part
    const next               = { ...part, status: auto.status }
    if (auto.status === 'running') {
      delete next.finishedAt
      const kept = part.status === 'running' ? part.startedAt : undefined
      next.startedAt = auto.startedAt === undefined ? kept ?? now : Math.min(kept ?? auto.startedAt, auto.startedAt)
    } else {
      next.startedAt = auto.startedAt ?? part.startedAt ?? now
      next.finishedAt = auto.finishedAt ?? (part.status === auto.status && part.finishedAt !== undefined ? part.finishedAt : now)
    }
    if (auto.progress !== undefined) next.progress = auto.progress
    if (auto.progressFrac !== undefined) next.progressFrac = auto.progressFrac
    if (JSON.stringify(next) === JSON.stringify(part)) return part
    changed = true
    return next
  })
  return changed ? { ...schedule, parts, updatedAt: now } : undefined
}

/** True when some part follows agents, so a journal scan is worth running. */
const tracksAgents = (schedule          ) => schedule.parts.some(p => !p.pinned && (p.track?.agents?.length ?? 0) > 0)

const keepNewest = (list                ) =>
  list.length <= MAX_AGENTS ? list : [...list].sort((a, b) => a.startedAt - b.startedAt).slice(-MAX_AGENTS)

/** Records an agent that started (a repeat of a known id changes nothing). */
function startAgent(list                         , agent              )                 {
  if (list.some(a => a.id === agent.id)) return [...list]
  return keepNewest([...list, agent])
}

/** Records the end of an agent's run; an agent already ended or never seen is left. */
function endAgent(list                         , id        , status                   , endedAt        )                 {
  return list.map(a => (a.id === id && a.status === 'running' ? { ...a, status, endedAt } : a))
}

/**
 * Folds the journal scan into what was seen live. An agent is the same one by id, or by
 * run and label (in case the two ids are spelled apart). An end seen either way stands.
 */
function mergeScan(list                         , scanned                         )                 {
  const out = [...list]
  for (const s of scanned) {
    const i = out.findIndex(a => a.id === s.id || (s.runId !== undefined && a.runId === s.runId && a.label === s.label))
    if (i < 0) {
      out.push(s)
      continue
    }
    const a = out[i] 
    const merged               = { ...a, label: a.label || s.label, startedAt: Math.min(a.startedAt, s.startedAt) }
    if (s.runId !== undefined && merged.runId === undefined) merged.runId = s.runId
    if (a.status === 'running' && s.status !== 'running') {
      merged.status = s.status
      merged.endedAt = s.endedAt ?? a.endedAt
    }
    out[i] = merged
  }
  return keepNewest(out)
}

/** The desktop task list tool's arguments, as far as the plan needs them. */
                        
                                                        
                   
                 
                
 

const isStepStatus = (v         )                          => v === 'pending' || v === 'in_progress' || v === 'completed'

/** Applies one update_plan call to the task list (the same reading agent-sprites uses). */
function applyPlanCall(list                     , call          )             {
  if (Array.isArray(call.items)) {
    return call.items.map(item => ({
      content: typeof item.content === 'string' ? item.content : '',
      status: isStepStatus(item.status) ? item.status : 'pending',
    }))
  }
  let next = [...list]
  if (Array.isArray(call.done)) {
    next = next.map((s, i) => (call.done .includes(i + 1) ? { ...s, status: 'completed' } : s))
  }
  if (call.advance === true) {
    const current = next.findIndex(s => s.status === 'in_progress')
    next = next.map((s, i) => (i === current ? { ...s, status: 'completed' } : s))
    const following = next.findIndex((s, i) => i > current && s.status === 'pending')
    next = next.map((s, i) => (i === following ? { ...s, status: 'in_progress' } : s))
  }
  if (typeof call.start === 'number') {
    next = next.map((s, i) => (i === call.start  - 1 ? { ...s, status: 'in_progress' } : s))
  }
  return next
}

/**
 * Lists this session's workflow agents from their journals: started and result entries
 * by agent id and label, start and end times from each agent's transcript, and runs that
 * ended without an agent's result (a stopped run) counted as failed for that agent.
 *
 * argv: <cwd> <sessionId>. Prints a JSON list of TrackedAgent (times may be null).
 */
const TRACK_PY = String.raw`
import datetime, json, os, re, sys

cwd, sid = sys.argv[1], sys.argv[2]
proj = os.path.join(os.path.expanduser('~/.claude/projects'), re.sub('[^A-Za-z0-9]', '-', cwd))
base = os.path.join(proj, sid)
runs_dir = os.path.join(base, 'subagents', 'workflows')
ended_dir = os.path.join(base, 'workflows')

def ms(ts):
    try:
        return int(datetime.datetime.fromisoformat(ts.replace('Z', '+00:00')).timestamp() * 1000)
    except Exception:
        return None

def stamp(raw):
    try:
        e = json.loads(raw)
    except Exception:
        return None
    t = e.get('timestamp') if isinstance(e, dict) else None
    return ms(t) if isinstance(t, str) else None

def first_ts(path):
    try:
        with open(path, 'rb') as f:
            for i, raw in enumerate(f):
                if i > 20:
                    break
                t = stamp(raw)
                if t is not None:
                    return t
    except OSError:
        pass
    return None

def last_ts(path):
    try:
        with open(path, 'rb') as f:
            f.seek(0, 2)
            size = f.tell()
            f.seek(max(0, size - 65536))
            lines = f.read().split(b'\n')
        for raw in reversed(lines):
            t = stamp(raw)
            if t is not None:
                return t
    except OSError:
        pass
    return None

def label_of(run_dir, aid):
    try:
        with open(os.path.join(run_dir, 'agent-' + aid + '.meta.json')) as f:
            return json.load(f).get('description') or ''
    except Exception:
        return ''

out = []
if os.path.isdir(runs_dir):
    for run in sorted(os.listdir(runs_dir)):
        run_dir = os.path.join(runs_dir, run)
        journal = os.path.join(run_dir, 'journal.jsonl')
        if not os.path.isfile(journal):
            continue
        run_ended = os.path.isfile(os.path.join(ended_dir, run + '.json'))
        agents = {}
        with open(journal, 'rb') as f:
            for raw in f:
                try:
                    e = json.loads(raw)
                except Exception:
                    continue
                aid = e.get('agentId') if isinstance(e, dict) else None
                if not aid:
                    continue
                a = agents.setdefault(aid, {'label': e.get('label') or '', 'result': None})
                if not a['label'] and e.get('label'):
                    a['label'] = e['label']
                if e.get('type') == 'result':
                    a['result'] = 'ok' if e.get('result') is not None else 'none'
        for aid, a in agents.items():
            transcript = os.path.join(run_dir, 'agent-' + aid + '.jsonl')
            if a['result'] == 'ok':
                status = 'done'
            elif a['result'] == 'none' or run_ended:
                status = 'failed'
            else:
                status = 'running'
            rec = {'id': aid, 'label': a['label'] or label_of(run_dir, aid), 'runId': run, 'status': status, 'startedAt': first_ts(transcript)}
            if status != 'running':
                rec['endedAt'] = last_ts(transcript)
            out.append(rec)
print(json.dumps(out))
`

/** Reads the scan's output; times it could not find become `now`. */
function parseScan(stdout        , now        )                             {
  try {
    const rows = JSON.parse(stdout)           
    if (!Array.isArray(rows)) return undefined
    const out                 = []
    for (const r of rows                                  ) {
      if (typeof r.id !== 'string' || typeof r.label !== 'string') continue
      const status = r.status === 'done' || r.status === 'failed' ? r.status : 'running'
      const agent               = { id: r.id, label: r.label, status, startedAt: typeof r.startedAt === 'number' ? r.startedAt : now }
      if (typeof r.runId === 'string') agent.runId = r.runId
      if (status !== 'running') agent.endedAt = typeof r.endedAt === 'number' ? r.endedAt : now
      out.push(agent)
    }
    return out
  } catch {
    return undefined
  }
}

return { MAX_AGENTS, globRegex, matching, planStepFor, autoFor, derive, tracksAgents, startAgent, endAgent, mergeScan, applyPlanCall, TRACK_PY, parseScan };
